  $tmrejson${"slug": "theories-and-methods-in-the-study-of-religion", "title": "Theories and Methods in the Study of Religion", "description": "Students define religion as an analytic category, explain major theories, match methods to evidence, critique categories and power relations, design ethical research, and apply multiple methods to a single case.", "topics": [{"id": "2e40d2e5-2d54-4b2d-9747-8ad9b924d5e0", "type": "topic", "title": "Studying Religion: Field Formation, Definitions, and Methodological Reflexivity", "description": "This opening unit treats religion as an analytic category rather than a self-evident object. Students learn why definitions matter, how the field formed, and how researchers account for their own assumptions.", "children": [{"id": "00111c7c-5f74-4b49-b334-41b36842b382", "type": "subtopic", "title": "Defining religion", "children": [{"id": "37c229ae-14a9-41cc-a824-728e6b9fc797", "type": "concept", "title": "Specific terms and topics:"}, {"id": "9ecf8073-2ce7-4f10-9753-249f88914cf3", "type": "concept", "title": "substantive definition"}, {"id": "63a0dc93-740d-4284-a0cf-7a085d598201", "type": "concept", "title": "functional definition"}, {"id": "0b892742-aa61-4b8d-95e3-9fdeaab2775d", "type": "concept", "title": "family resemblance"}, {"id": "57720b58-4ac5-4e6a-8954-faa3d310cff0", "type": "concept", "title": "sui generis claims"}, {"id": "ecf3d608-660d-4477-a92a-0d260e666127", "type": "concept", "title": "belief"}, {"id": "d3a65be1-592d-4334-866a-f5908be7ea50", "type": "concept", "title": "practice"}, {"id": "cefec0a1-b283-485a-ac8f-3359827125a5", "type": "concept", "title": "sacred/profane"}, {"id": "317f0eac-25d1-4b75-bf3c-3f7817c2892d", "type": "concept", "title": "ultimate concern"}, {"id": "1ca5fce8-652b-41b9-98c4-abeba3b337d0", "type": "concept", "title": "worldview"}, {"id": "4b55b620-2878-4f51-bd05-abf0dbd5d879", "type": "concept", "title": "boundary problem"}], "description": "Students compare substantive, functional, family-resemblance, and discourse-based definitions so they can see what each definition includes, excludes, and makes visible."}, {"id": "5ba7530b-4be5-4131-93b3-1542fc9442b4", "type": "subtopic", "title": "Field genealogy", "children": [{"id": "d073940f-edde-4fc8-af80-3c997642889b", "type": "concept", "title": "Specific terms and topics:"}, {"id": "52669b0d-71ce-4077-88ff-135dbc1df35f", "type": "concept", "title": "comparative religion"}, {"id": "612edb41-c5d3-43a2-990b-040e76337dc8", "type": "concept", "title": "history of religions"}, {"id": "128d8590-df6a-4369-8d5f-d3dea45f7c9a", "type": "concept", "title": "religionswissenschaft"}, {"id": "8f24210c-3338-4693-9460-03c456fec44d", "type": "concept", "title": "area studies"}, {"id": "52925eb1-90d4-416b-9c40-d8e844a7740e", "type": "concept", "title": "philology"}, {"id": "04111766-6072-4fc2-8197-44e3ca05c3c0", "type": "concept", "title": "missionary archives"}, {"id": "89283a3c-3506-4e19-a374-b4d0c644c50c", "type": "concept", "title": "colonial knowledge"}, {"id": "1356d80e-2cbe-4db5-af55-8580b35e9b6c", "type": "concept", "title": "secular university"}, {"id": "760faf41-ecd6-4cfb-ae74-6c0abdec4af2", "type": "concept", "title": "departmental formation"}, {"id": "34423f37-7c36-4e11-8c24-e25671a3cf15", "type": "concept", "title": "disciplinary boundary"}], "description": "This subtopic traces the academic study of religion through philology, comparative religion, anthropology, sociology, theology-adjacent institutions, and secular university settings."}, {"id": "466b1d19-26fd-4d45-a4c2-4792374936aa", "type": "subtopic", "title": "Reflexivity and positionality", "children": [{"id": "ef6ca78d-8e26-4955-9a34-7e2e2a06f365", "type": "concept", "title": "Specific terms and topics:"}, {"id": "b9100673-1feb-4d36-85c2-c66f508b94c9", "type": "concept", "title": "researcher positionality"}, {"id": "ca4b6fbf-99e7-4e4f-a56f-cc8ce4f96691", "type": "concept", "title": "reflexivity"}, {"id": "2906764f-5d21-424f-9620-f084d5859285", "type": "concept", "title": "insider/outsider problem"}, {"id": "2a46d6ae-1f6a-4d44-a44a-dd86793ee514", "type": "concept", "title": "emic/etic language"}, {"id": "a826ede6-0e8a-4f1a-a8ec-8c4c28e8d2aa", "type": "concept", "title": "reflexive memo"}, {"id": "d7887a19-77f5-4d82-a69a-dbfaa69734e4", "type": "concept", "title": "standpoint"}, {"id": "45876089-0f09-4414-b0b3-7c9d0e860757", "type": "concept", "title": "objectivity"}, {"id": "8f99699a-b65e-440c-a7b2-15c02db938e1", "type": "concept", "title": "situated knowledge"}, {"id": "e58973cf-227e-4f5f-8a3c-07c597733863", "type": "concept", "title": "bias audit"}, {"id": "e67651da-1cab-410e-a801-51e3cfe26a48", "type": "concept", "title": "translation of categories"}, {"id": "21461240-a488-461e-9800-d818847a71e3", "type": "concept", "title": "interpretive humility"}], "description": "Students practice naming how social location, training, language ability, commitments, and institutional power shape research questions and interpretation."}]}, {"id": "3ac92170-a618-4f18-8557-0206860bdbd6", "type": "topic", "title": "Classical Evolutionary and Comparative Theories of Religion", "description": "This unit examines nineteenth- and early twentieth-century theories that still shape the field, while also teaching students how to critique evolutionism, reductionism, and universalizing claims.", "children": [{"id": "3649a639-c25f-41ec-a218-eb1d4e75e0b0", "type": "subtopic", "title": "Evolutionary models", "children": [{"id": "d72ff78a-17b4-4cf9-a01e-104b94fedc5d", "type": "concept", "title": "Specific terms and topics:"}, {"id": "71ba80b6-eba9-443c-96fc-d944b2564b5b", "type": "concept", "title": "animism"}, {"id": "eb507c57-2765-4da1-a18c-3811cda0056b", "type": "concept", "title": "totemism"}, {"id": "8850e934-e0c0-471b-87f5-f245159d5723", "type": "concept", "title": "fetishism"}, {"id": "12acc549-aaed-4a1d-aa2e-99758b766442", "type": "concept", "title": "magic-to-religion-to-science"}, {"id": "ba3e2e76-1255-495a-938a-a7370757d5d1", "type": "concept", "title": "survivals"}, {"id": "a7b43f03-761b-456b-b632-c4709faf22b9", "type": "concept", "title": "primitive religion"}, {"id": "10858fe4-9545-45ac-b412-25b760437452", "type": "concept", "title": "social evolutionism"}, {"id": "254d9a25-8cce-45ca-9186-7385612fa47e", "type": "concept", "title": "civilization scale"}, {"id": "53f369b3-1e10-4061-a857-0b3428a3441b", "type": "concept", "title": "Tylor"}, {"id": "85d95901-b1a9-4057-8fa7-3713ebe6c449", "type": "concept", "title": "Frazer"}], "description": "Students learn how early theorists ordered religions into developmental sequences and why those sequences are now methodologically suspect but historically influential."}, {"id": "13f2a217-d3d0-4e7f-b0f6-dab6c2410b93", "type": "subtopic", "title": "Reductionist explanations", "children": [{"id": "25743b05-2e9f-494e-9cdd-13abf3253932", "type": "concept", "title": "Specific terms and topics:"}, {"id": "3d11558c-a496-4f2c-952c-658e1aa1812b", "type": "concept", "title": "Marx"}, {"id": "25d32c60-69da-457a-9c0a-6bbf9ac2268c", "type": "concept", "title": "Freud"}, {"id": "5673df0d-c49f-4509-8a2b-091863a3ec3c", "type": "concept", "title": "Durkheim"}, {"id": "2c82b0db-9d8b-454d-8f8f-8da10cb0fb98", "type": "concept", "title": "projection"}, {"id": "1e0ff984-ac74-4819-a34a-8c9ea0d5b7b9", "type": "concept", "title": "opium of the people"}, {"id": "9d88686e-66e5-4850-a033-73a80bc5d031", "type": "concept", "title": "wish fulfillment"}, {"id": "a9834465-710a-4ef9-a6fc-466aa4a3e619", "type": "concept", "title": "collective effervescence"}, {"id": "247eeaef-3ce0-4b0e-8922-8b318979d767", "type": "concept", "title": "social function"}, {"id": "a8042a7f-55b4-441a-95bd-0f6b24f3c0aa", "type": "concept", "title": "alienation"}, {"id": "aea4e1e2-5232-4cac-b316-b07d56c825a1", "type": "concept", "title": "false consciousness"}], "description": "This subtopic compares theories that explain religion through economics, psychology, society, or power rather than through religious truth claims themselves."}, {"id": "a63c4be9-709a-4ce0-a843-1a1be88a7315", "type": "subtopic", "title": "Critiquing the classics", "children": [{"id": "e0b64c3e-eeea-41ca-a88b-19c8ec0d5b42", "type": "concept", "title": "Specific terms and topics:"}, {"id": "3f3d0ceb-4f9f-40bb-be78-5f0431b72a84", "type": "concept", "title": "Eurocentrism"}, {"id": "618b8b61-efa9-4cd9-b397-9409073a3116", "type": "concept", "title": "androcentrism"}, {"id": "69e8b807-c4da-4528-879a-59e572c92c56", "type": "concept", "title": "colonial comparison"}, {"id": "dc988c2f-3a03-4207-933d-e48f7824b4f0", "type": "concept", "title": "armchair anthropology"}, {"id": "6a32274b-b298-4a94-b82f-3f1b802a0044", "type": "concept", "title": "evidence base"}, {"id": "dd82dbbb-a962-4c87-b76f-3d696d551e7b", "type": "concept", "title": "universalism"}, {"id": "a23db848-0a97-430a-97f1-2f478a2b0505", "type": "concept", "title": "essentialism"}, {"id": "2a942396-42b3-4d0f-a490-7952e7aa0ce8", "type": "concept", "title": "anachronism"}, {"id": "725abc66-34c0-41f7-a764-c02814d57416", "type": "concept", "title": "canon formation"}, {"id": "ba5aee4e-d4cf-4e38-b90e-e2c857ee4e34", "type": "concept", "title": "theory after critique"}], "description": "Students learn to use classic texts as historical artifacts and analytic tools without treating their categories as neutral or timeless."}]}, {"id": "623d062c-c5e9-47d3-8037-c7a7f62cb891", "type": "topic", "title": "Sociology of Religion: Society, Authority, Rationalization, and Secularization", "description": "This unit studies religion as a social institution, source of authority, form of community, and arena of change. It links classic sociology to contemporary questions about pluralism and public life.", "children": [{"id": "a8256fe7-b2d5-449b-8221-b8693196fcbf", "type": "subtopic", "title": "Religion and social order", "children": [{"id": "fd627870-2fdd-4a4d-aa15-4d56fbe4338e", "type": "concept", "title": "Specific terms and topics:"}, {"id": "ab1b4203-c45b-4cfb-b303-9a7e56d42d9b