t", "title": "disenchantment"}, {"id": "93eda0d6-8427-4d72-89fd-9dc719eb278c", "type": "concept", "title": "rationalization"}, {"id": "bd200dd1-47e4-45ec-8779-413dcd54a435", "type": "concept", "title": "elective affinity"}], "description": "This subtopic uses Weber and later sociology to analyze charisma, bureaucracy, routinization, and religious change under modern institutions."}, {"id": "70889473-b22e-483c-805b-ced30ae80b9f", "type": "subtopic", "title": "Secularization and pluralism", "children": [{"id": "80219e2d-1fae-46a7-bc71-7b3d626827bc", "type": "concept", "title": "Specific terms and topics:"}, {"id": "f05db924-1250-4110-976d-8cafe17f0744", "type": "concept", "title": "secularization thesis"}, {"id": "41545930-d1e0-49cc-9b1e-26b7ad9ccfca", "type": "concept", "title": "differentiation"}, {"id": "064eb490-5487-468a-b277-a764120273b7", "type": "concept", "title": "privatization"}, {"id": "40a91f7e-5a59-476e-9a8e-3d1ac0e61f42", "type": "concept", "title": "religious economies"}, {"id": "a178e863-f1ca-4216-bace-c6801dadcf3b", "type": "concept", "title": "pluralism"}, {"id": "f50a1932-97e7-4eeb-bd21-e60f45b7cbf1", "type": "concept", "title": "nones"}, {"id": "b02f2904-7d25-4f9a-91e3-f5d39046d8fb", "type": "concept", "title": "spiritual but not religious"}, {"id": "188d6d3a-87a5-4012-b86f-07cecc83a032", "type": "concept", "title": "postsecular"}, {"id": "77dfe335-7d01-43db-b774-0d0c71de8b66", "type": "concept", "title": "desecularization"}, {"id": "810c50d5-445f-4e4c-bbcf-b23487ec6087", "type": "concept", "title": "public religion"}], "description": "Students learn the competing claims around decline, differentiation, privatization, market choice, lived spirituality, and postsecular public religion."}]}, {"id": "2d0590a0-43a7-4418-9efd-94560f029f00", "type": "topic", "title": "Anthropology and Ethnography of Religion", "description": "This unit teaches religion through fieldwork, thick description, practice, and everyday life. It emphasizes how scholars learn fr