 for"}, {"id": "5f94f29f-b395-46aa-82a3-82a05a38ec2d", "type": "concept", "title": "cultural system"}, {"id": "17aa45ca-2dd7-483e-977b-778b655f6c26", "type": "concept", "title": "meaning"}, {"id": "be964bc1-63f5-48ac-97c0-b0d0be0f0a03", "type": "concept", "title": "description versus explanation"}, {"id": "5b6a40b5-b8ac-46d2-818c-fe669a63113f", "type": "concept", "title": "interpretive circle"}, {"id": "dc8ee85c-e789-4efb-bc9e-87977f8ec063", "type": "concept", "title": "local knowledge"}, {"id": "dc7f3463-8301-40f8-9841-4230358dc95a", "type": "concept", "title": "anti-anti-relativism"}], "description": "This subtopic introduces culture as webs of meaning and religion as a system of symbols, while also examining critiques of symbolic interpretation."}, {"id": "a8695e67-916e-46de-a7ed-9edde49cfe2e", "type": "subtopic", "title": "Ethics of representation", "children": [{"id": "e19fd78c-903e-4083-a8d3-5f7418101fc9", "type": "concept", "title": "Specific terms and topics:"}, {"id": "05e34f34-72b9-4ae7-a3f9-f897427905d7", "type": "concept", "title": "informed consent"}, {"id": "4f05e47d-a0d0-42df-bb50-99e150425227", "type": "concept", "title": "confidentiality"}, {"id": "13089d56-9b64-41c4-b430-a60187c8ada3", "type": "concept", "title": "pseudonym"}, {"id": "4b497571-8ddf-43dc-b600-99370a54a879", "type": "concept", "title": "reciprocity"}, {"id": "3a22318e-045c-414c-b890-d6c94cf26f9c", "type": "concept", "title": "IRB"}, {"id": "e93988df-2755-4dda-9ed2-e30fa73b5bd6", "type": "concept", "title": "harm minimization"}, {"id": "db314a47-e35b-4fd7-a6ba-bab3abbf324d", "type": "concept", "title": "collaborative ethnography"}, {"id": "62fbc9bf-d397-40ea-a196-9cbe9bbfe785", "type": "concept", "title": "member checking"}, {"id": "57e4d70d-b1cd-4875-ae78-dc18f0b8a8cf", "type": "concept", "title": "representation"}, {"id": "fd2bc144-de3a-4379-9df6-6678c1af05a1", "type": "concept", "title": "extractive research"}], "description": "Students practice writing about communities without exoticizing, appropriating, flattening difference, or exposing vulnerable participants."}]}, {"id": "db47b2c4-2c8f-4a7b-b2e8-1257b1f16a86", "type": "topic", "title": "Phenomenology, Hermeneutics, and Comparative Religion", "description": "This unit studies religious experience, interpretation, and comparison. Students learn why these methods were influential and how later scholars challenged their assumptions.", "children": [{"id": "9f140740-a7cb-47fd-b8e4-29ddf1298568", "type": "subtopic", "title": "Phenomenology of religion", "children": [{"id": "e0b4a390-f347-43fe-8e75-747a58e08fa8", "type": "concept", "title": "Specific terms and topics:"}, {"id": "575c7245-bd23-4f9c-b60b-8df0683c5a00", "type": "concept", "title": "Eliade"}, {"id": "f61cff22-df3b-4537-bc48-d8fc482e7808", "type": "concept", "title": "hierophany"}, {"id": "41861a3d-d6ed-4ded-bbea-e744e2f04153", "type": "concept", "title": "axis mundi"}, {"id": "7762b9ae-b98c-4686-8e5d-2c99d391a477", "type": "concept", "title": "sacred space"}, {"id": "4e41a9d5-449e-45ed-8040-324dfaf5e38f", "type": "concept", "title": "sacred time"}, {"id": "3597338b-2a8a-4220-bd2e-3a896eedf644", "type": "concept", "title": "myth of eternal return"}, {"id": "4401f674-a566-4d9d-b521-d8d359985180", "type": "concept", "title": "bracketing"}, {"id": "e8f4474f-21b2-4bf8-8b92-caa5c93b431c", "type": "concept", "title": "essence"}, {"id": "1d8987fe-bbe5-45a1-a2d3-db744164d2b7", "type": "concept", "title": "experience"}, {"id": "1e490bfd-333e-4b57-b3c0-444000504ecb", "type": "concept", "title": "morphology"}], "description": "Students examine attempts to describe religious experience and sacred meaning from the standpoint of practitioners, while evaluating claims to neutrality."}, {"id": "66ce0937-02f8-4532-b4a9-895d83e2fa6c", "type": "subtopic", "title": "Hermeneutics", "children": [{"id": "0dc65166-040f-408f-bb61-593ac2db0d02", "type": "concept", "title": "Specific terms and topics:"}, {"id": "21786dc6-7021-480c-aa60-111064517a78", "type": 