chy"}, {"id": "98a792ae-bcbc-4ae9-a965-3d007a1ca1aa", "type": "concept", "title": "gendered authority"}, {"id": "48a57d31-a89e-4833-aa79-3a036e617c4e", "type": "concept", "title": "women's ritual"}, {"id": "ede0c967-6a03-4df4-9f96-53e28032d28b", "type": "concept", "title": "domestic religion"}, {"id": "1b9aa4fc-ef5e-4166-a3e7-23e9828c5200", "type": "concept", "title": "reproductive labor"}, {"id": "ade617f3-986f-4f8c-bd44-34683d4d7ac2", "type": "concept", "title": "intersectionality"}, {"id": "faff777d-251e-410d-9422-1094eb690ad6", "type": "concept", "title": "agency"}, {"id": "9400f6b0-9257-4166-81cd-79ab87740d7d", "type": "concept", "title": "recovery history"}, {"id": "e7f84fe0-ae3e-4e92-97b0-34f4b8a9bc2b", "type": "concept", "title": "feminist hermeneutics"}], "description": "Students study how feminist scholarship critiques androcentric sources and recovers women, gendered labor, authority, and lived practice."}, {"id": "eca5b28f-d1cf-412a-8363-0a6e2f1411c4", "type": "subtopic", "title": "Queer and sexuality studies", "children": [{"id": "01021cea-8066-45a0-a466-73fa2299b974", "type": "concept", "title": "Specific terms and topics:"}, {"id": "05b94cc6-f296-421a-897c-0e03d0d01f0b", "type": "concept", "title": "heteronormativity"}, {"id": "67be99b1-7bba-45ac-a495-7f0ce28646a4", "type": "concept", "title": "queer hermeneutics"}, {"id": "95fcefd6-6c82-46aa-83ed-edb23ce66123", "type": "concept", "title": "sexual ethics"}, {"id": "fd682fd5-cbfb-494a-8a68-2f4c6197ce9b", "type": "concept", "title": "purity discourse"}, {"id": "42e91546-2189-4aec-88a7-6b3611dd8661", "type": "concept", "title": "celibacy"}, {"id": "5ba606fb-308c-4905-9d45-8f8d2fa64618", "type": "concept", "title": "marriage"}, {"id": "69079e83-a531-44c9-a86c-f2b0dabd1741", "type": "concept", "title": "kinship"}, {"id": "c4b5a696-d3d0-48f5-bb15-49c2e66d22d5", "type": "concept", "title": "trans embodiment"}, {"id": "4d4c8bb1-3a22-4772-b65d-698bcde6f467", "type": "concept", "title": "desire"}, {"id": "c8e8f