ty"}, {"id": "e86fd0bb-60c8-44b6-bd9e-b470bb87a749", "type": "concept", "title": "commodification"}, {"id": "5ac1922b-aa8d-46af-9d1b-8b89c0096930", "type": "concept", "title": "genre"}, {"id": "101b6845-4bbe-4c1e-b531-c3e69a6a208e", "type": "concept", "title": "audience reception"}, {"id": "7e946987-2e78-40ea-94c1-e5d1cb52b2d3", "type": "concept", "title": "cultural appropriation"}, {"id": "debf173a-1ae2-465b-b0bc-1f92e9eb475a", "type": "concept", "title": "public pedagogy"}], "description": "Students learn to use film, television, music, comics, games, and fandom as sources for analyzing religious symbols and anxieties."}]}, {"id": "2dd4e426-bc09-49c0-9cd2-65e12e0ba268", "type": "topic", "title": "Comparison, Translation, Classification, and Category Critique", "description": "This unit equips students to use comparison carefully. It focuses on the categories scholars inherit, translate, invent, and revise.", "children": [{"id": "db84c2d7-96f4-4772-b315-f192999f2b75", "type": "subtopic", "title": "Classification systems", "children": [{"id": "b6297301-79b3-4d37-b09a-86dc9f9e6251", "type": "concept", "title": "Specific terms and topics:"}, {"id": "681bb0a0-8e13-4d76-a103-e89dd1d29cde", "type": "concept", "title": "world religions paradigm"}, {"id": "955084b0-3e5c-4f52-b782-04dbc97358e6", "type": "concept", "title": "sect"}, {"id": "f2ee0247-bbf4-4012-a30b-436a3b96adfd", "type": "concept", "title": "cult"}, {"id": "42f776bf-2a04-4fef-91de-839bf982726f", "type": "concept", "title": "new religious movement"}, {"id": "5dd71be2-4caa-4b4c-b074-b19ebcf2cf08", "type": "concept", "title": "magic"}, {"id": "6e052c4e-74a9-47ec-b59e-f4c89ebb5ff6", "type": "concept", "title": "mysticism"}, {"id": "4b33fc86-9960-4cd3-8669-a159fdeb720e", "type": "concept", "title": "tradition"}, {"id": "24c6d717-bf3d-40f7-aaf8-55a4a73de314", "type": "concept", "title": "orthodoxy"}, {"id": "e479cc8b-3598-4916-b737-546b4c85dec3", "type": "concept", "title": "heresy"}, {"id": "68b3fad4-3632-4fbb-86d