  data = $tmrejson${"slug": "theories-and-methods-in-the-study-of-religion", "title": "Theories and Methods in the Study of Religion", "description": "Students define religion as an analytic category, explain major theories, match methods to evidence, critique categories and power relations, design ethical research, and apply multiple methods to a single case.", "topics": [{"id": "2e40d2e5-2d54-4b2d-9747-8ad9b924d5e0", "type": "topic", "title": "Studying Religion: Field Formation, Definitions, and Methodological Reflexivity", "description": "This opening unit treats religion as an analytic category rather than a self-evident object. Students learn why definitions matter, how the field formed, and how researchers account for their own assumptions.", "children": [{"id": "00111c7c-5f74-4b49-b334-41b36842b382", "type": "subtopic", "title": "Defining religion", "children": [{"id": "37c229ae-14a9-41cc-a824-728e6b9fc797", "type": "concept", "title": "Specific terms and topics:"}, {"id": "9ecf8073-2ce7-4f10-9753-249f88914cf3", "type": "concept", "title": "substantive definition"}, {"id": "63a0dc93-740d-4284-a0cf-7a085d598201", "type": "concept", "title": "functional definition"}, {"id": "0b892742-aa61-4b8d-95e3-9fdeaab2775d", "type": "concept", "title": "family resemblance"}, {"id": "57720b58-4ac5-4e6a-8954-faa3d310cff0", "type": "concept", "title": "sui generis claims"}, {"id": "ecf3d608-660d-4477-a92a-0d260e666127", "type": "concept", "title": "belief"}, {"id": "d3a65be1-592d-4334-866a-f5908be7ea50", "type": "concept", "title": "practice"}, {"id": "cefec0a1-b283-485a-ac8f-3359827125a5", "type": "concept", "title": "sacred/profane"}, {"id": "317f0eac-25d1-4b75-bf3c-3f7817c2892d", "type": "concept", "title": "ultimate concern"}, {"id": "1ca5fce8-652b-41b9-98c4-abeba3b337d0", "type": "concept", "title": "worldview"}, {"id": "4b55b620-2878-4f51-bd05-abf0dbd5d879", "type": "concept", "title": "boundary problem"}], "description": "Students compare substantive, functional, famil