": "concept", "title": "survivals"}, {"id": "a7b43f03-761b-456b-b632-c4709faf22b9", "type": "concept", "title": "primitive religion"}, {"id": "10858fe4-9545-45ac-b412-25b760437452", "type": "concept", "title": "social evolutionism"}, {"id": "254d9a25-8cce-45ca-9186-7385612fa47e", "type": "concept", "title": "civilization scale"}, {"id": "53f369b3-1e10-4061-a857-0b3428a3441b", "type": "concept", "title": "Tylor"}, {"id": "85d95901-b1a9-4057-8fa7-3713ebe6c449", "type": "concept", "title": "Frazer"}], "description": "Students learn how early theorists ordered religions into developmental sequences and why those sequences are now methodologically suspect but historically influential."}, {"id": "13f2a217-d3d0-4e7f-b0f6-dab6c2410b93", "type": "subtopic", "title": "Reductionist explanations", "children": [{"id": "25743b05-2e9f-494e-9cdd-13abf3253932", "type": "concept", "title": "Specific terms and topics:"}, {"id": "3d11558c-a496-4f2c-952c-658e1aa1812b", "type": "concept", "title": "Marx"}, {"id": "25d32c60-69da-457a-9c0a-6bbf9ac2268c", "type": "concept", "title": "Freud"}, {"id": "5673df0d-c49f-4509-8a2b-091863a3ec3c", "type": "concept", "title": "Durkheim"}, {"id": "2c82b0db-9d8b-454d-8f8f-8da10cb0fb98", "type": "concept", "title": "projection"}, {"id": "1e0ff984-ac74-4819-a34a-8c9ea0d5b7b9", "type": "concept", "title": "opium of the people"}, {"id": "9d88686e-66e5-4850-a033-73a80bc5d031", "type": "concept", "title": "wish fulfillment"}, {"id": "a9834465-710a-4ef9-a6fc-466aa4a3e619", "type": "concept", "title": "collective effervescence"}, {"id": "247eeaef-3ce0-4b0e-8922-8b318979d767", "type": "concept", "title": "social function"}, {"id": "a8042a7f-55b4-441a-95bd-0f6b24f3c0aa", "type": "concept", "title": "alienation"}, {"id": "aea4e1e2-5232-4cac-b316-b07d56c825a1", "type": "concept", "title": "false consciousness"}], "description": "This subtopic compares theories that explain religion through economics, psychology, society, or power rather than through religious truth claims themselves."}, {"id": "a63c4be9-709a-4ce0-a843-1a1be88a7315", "type": "subtopic", "title": "Critiquing the classics", "children": [{"id": "e0b64c3e-eeea-41ca-a88b-19c8ec0d5b42", "type": "concept", "title": "Specific terms and topics:"}, {"id": "3f3d0ceb-4f9f-40bb-be78-5f0431b72a84", "type": "concept", "title": "Eurocentrism"}, {"id": "618b8b61-efa9-4cd9-b397-9409073a3116", "type": "concept", "title": "androcentrism"}, {"id": "69e8b807-c4da-4528-879a-59e572c92c56", "type": "concept", "title": "colonial comparison"}, {"id": "dc988c2f-3a03-4207-933d-e48f7824b4f0", "type": "concept", "title": "armchair anthropology"}, {"id": "6a32274b-b298-4a94-b82f-3f1b802a0044", "type": "concept", "title": "evidence base"}, {"id": "dd82dbbb-a962-4c87-b76f-3d696d551e7b", "type": "concept", "title": "universalism"}, {"id": "a23db848-0a97-430a-97f1-2f478a2b0505", "type": "concept", "title": "essentialism"}, {"id": "2a942396-42b3-4d0f-a490-7952e7aa0ce8", "type": "concept", "title": "anachronism"}, {"id": "725abc66-34c0-41f7-a764-c02814d57416", "type": "concept", "title": "canon formation"}, {"id": "ba5aee4e-d4cf-4e38-b90e-e2c857ee4e34", "type": "concept", "title": "theory after critique"}], "description": "Students learn to use classic texts as historical artifacts and analytic tools without treating their categories as neutral or timeless."}]}, {"id": "623d062c-c5e9-47d3-8037-c7a7f62cb891", "type": "topic", "title": "Sociology of Religion: Society, Authority, Rationalization, and Secularization", "description": "This unit studies religion as a social institution, source of authority, form of community, and arena of change. It links classic sociology to contemporary questions about pluralism and public life.", "children": [{"id": "a8256fe7-b2d5-449b-8221-b8693196fcbf", "type": "subtopic", "title": "Religion and social order", "children": [{"id": "fd627870-2fdd-4a4d-aa15-4d56fbe4338e", "type": "concept", "title": "Specific terms and topics:"}, {"id": "ab1b4203-c45b-4cfb-b303-9a7e5